    // estimate: lastIrrigationDays * mean daily ETc
    const lastD = opts.lastIrrigationDays || 10;
    const meanEtc = mean(etcDaily.length ? etcDaily : [2]) || 2;
    depletionMm = lastD * meanEtc;
    estimated = true;
  }
