  // rain next 48h
  const rain48 = round1(sum(take(rows,48).map(r=>r.rain||0)));
  // ideal ranges and too-warm thresholds
  const ranges = {
    wheat: { min:16, max:22, tooWarm:25 },
    mustard: { min:18, max:25, tooWarm:28 },
    chickpea: { min:18, max:26, tooWarm:30 },
    potato: { min:15, max:25, tooWarm:30 }
  };
  const r = ranges[cropId];
  if (rain48 >= 20) {
    return { verdict: 'wait', tmean5, reason: 'heavy_rain' };
  }
  if (tmean5 == null) return { verdict: 'wait', tmean5, reason: 'no_temp' };
  if (tmean5 >= r.min && tmean5 <= r.max) {
    return { verdict: 'sow', tmean5, reason: 'within_range' };
  }
  if (tmean5 < r.min) {
    return { verdict: 'cold', tmean5, reason: 'too_cold' };
  }
  // tmean5 > r.max
  if (tmean5 > r.tooWarm) {
    return { verdict: 'wait', tmean5, reason: 'too_warm' };
  }
  return { verdict: 'late', tmean5, reason: 'marginally_warm' };
}

export function fertilizerAdvice(rows) {
  if (!rows || rows.length === 0) throw new Error('no data');
  const rain48 = round1(sum(take(rows,48).map(r=>r.rain||0)));
  if (rain48 >= 20) {
    return { verdict: 'hold', reason: 'heavy_rain_next_48h' };
  }
  return { verdict: 'go', reason: 'safe_to_topdress; if no rain, irrigate lightly after urea to reduce volatilization' };
}

export function plan(rows, { crop, stage, soil='loam', lastIrrigationDays } = {}) {
  if (!rows || rows.length === 0) throw new Error('no data');
  const generatedFrom = rows[0].t;
  const days = groupByDay(rows);
  const daySums = days.map(daySummary);
  const spray = sprayWindows(rows);
  const irrigation = irrigationAdvice(rows, crop, stage, { soil, lastIrrigationDays });
  const hazardsAll = hazards(rows, crop, stage);

  // assemble days array
  const daysOut = days.map((d, idx) => {
    const summary = daySummary(d);
    const sprayDay = spray.find(s=>s.date===d.date) || { date:d.date, windows:[], best:null, blockers:{} };
    const hazardsDay = hazardsAll.filter(h=>h.date===d.date);
    return {
      date: d.date,
      summary,
      spray: sprayDay,
      hazards: hazardsDay
    };
  });

  // today headlines: collect hazard stops first
  const todayDate = daysOut[0].date;
  const todaysHazards = hazardsAll.filter(h=>h.date===todayDate);
  const stopHazards = todaysHazards.filter(h=>h.level==='stop');
  const cautionHazards = todaysHazards.filter(h=>h.level==='caution');

  const headlines = [];
  for (const h of stopHazards) {
    headlines.push(`STOP: ${h.type} risk today (${h.level})`);
  }
  // irrigation headline
  headlines.push(`Irrigation: ${irrigation.decision}`);
  // spray best window for today
  const sprayToday = spray.find(s=>s.date===todayDate);
  if (sprayToday && sprayToday.best) {
    headlines.push(`Spray window today: ${sprayToday.best.start}–${sprayToday.best.end} (${sprayToday.best.level})`);
  } else {
    headlines.push('No suitable spray window today');
  }
  // include caution hazards after
  for (const h of cautionHazards) {
    headlines.push(`CAUTION: ${h.type} risk today`);
  }

  // Trace steps
  const trace = [];
  trace.push({ step: 'observe', detail: `${rows.length} hourly rows, ${daysOut.length} days, first date ${generatedFrom}` });
  // spray stats
  const sprayAll = spray;
  const totalGoodHours = sprayAll.reduce((acc,s)=>acc + (s.best ? (s.best.hours || 0) : 0), 0);
  trace.push({ step: 'rule', detail: `spray: best windows computed for ${sprayAll.length} days; today's best: ${spray.find(s=>s.date===todayDate && s.best)? spray.find(s=>s.date===todayDate).best.start+'-'+spray.find(s=>s.date===todayDate).best.end : 'none'}` });
  trace.push({ step: 'decide', detail: `irrigation: ${irrigation.decision} (rain72 ${irrigation.rain72} mm, depletion ${irrigation.depletionMm} mm)` });

  return {
    crop,
    stage,
    generatedFrom,
    days: daysOut,
    irrigation,
    sowing: sowingAdvice(rows, crop),
    fertilizer: fertilizerAdvice(rows),
    today: {
      headline: headlines
    },
    trace
  };
}

